import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十三卦 夬 泽天夬 兑上乾下","description":"周易 - 第四十三卦 夬 泽天夬 兑上乾下","frontmatter":{"title":"第四十三卦 夬 泽天夬 兑上乾下","description":"周易 - 第四十三卦 夬 泽天夬 兑上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/044.md","filePath":"zh/classics/zhouyi/044.md"}'),l={name:"zh/classics/zhouyi/044.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="夬" tabindex="-1">夬 <a class="header-anchor" href="#夬" aria-label="Permalink to “夬”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>扬于王庭，孚号，有厉，告自邑，不利即戎，利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>夬，决也，刚决柔也。健而说，决而和，扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上于天，夬；君子以施禄及下，居德则忌。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>壮于前趾，往不胜为吝。 象曰：不胜而往，咎也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>惕号，莫夜有戎，勿恤。象曰：莫夜有戎，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>壮于，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。象曰：君子夬夬，终无咎也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>臀无肤，其行次且。牵羊悔亡，闻言不信。象曰：其行次且，位不当也。闻言不信，聪不明也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>苋陆夬夬，中行无咎。象曰：中行无咎，中未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>无号，终有凶。象曰：无号之凶，终不可长也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
